// Category B — a one-line notice that scrolls sideways when it does not fit: the idle notice a kiosk
// draws above its start button (「'주문하기' 누르고 아바타와 음성 주문을 시작하세요」 over its English
// line).
//
// It sits on its own opaque surface: the idle wallpaper can be any image, so text drawn over a
// translucent wash could not promise contrast. That is the same ruling as ScanFrame's
// caption.
//
// Motion is optional, never required to read it:
// - It scrolls only while the text overflows.
// - Moving content that lasts past five seconds needs a way to stop it (WCAG 2.2.2), so pressing the
//   notice pauses and resumes it, through a toggle covering the notice and named by `pauseLabel`.
//   Paused, it stops and wraps, so the whole text is visible: the change in layout is the visible cue.
// - With prefers-reduced-motion it does not move at all: the text wraps instead, so nothing is cut off.
//
// The text is read once: the copy that loops the scroll is aria-hidden.
import { useLayoutEffect, useRef, useState } from "react";
import { ToggleButton } from "react-aria-components";
import type { CSSProperties, Ref } from "react";
import { useReducedMotion } from "./useReducedMotion";
import "./Marquee.css";

export interface MarqueeProps {
  /**
   * Size axis: the type rung and the inset.
   *
   * @default "medium"
   */
  size?: "small" | "medium" | "large";
  /** The notice, e.g. "'주문하기' 누르고 아바타와 음성 주문을 시작하세요". */
  text: string;
  /** A second line in a supporting ink, e.g. the English notice. */
  secondary?: string;
  /** Names the pause toggle, e.g. "공지 멈추기". Shown while the notice overflows, moving or paused. */
  pauseLabel: string;
  /** Additional class (optional). sd-marquee is always preserved. */
  className?: string;
  /** Forwarded to the root element. */
  ref?: Ref<HTMLDivElement>;
}

export function Marquee({ size = "medium", text, secondary, pauseLabel, className, ref }: MarqueeProps) {
  const still = useReducedMotion();
  const viewport = useRef<HTMLDivElement>(null);
  const line = useRef<HTMLSpanElement>(null);
  const track = useRef<HTMLDivElement>(null);
  // The overflowing width (0 when the text fits) and the loop's duration in seconds.
  const [overflow, setOverflow] = useState(0);
  const [loop, setLoop] = useState(0);
  const [paused, setPaused] = useState(false);

  useLayoutEffect(() => {
    const v = viewport.current;
    const l = line.current;
    if (!v || !l) return;
    const measure = () => {
      // A paused notice wraps, so it would read as fitting; keep the last measure until it resumes.
      if (paused) return;
      const w = l.scrollWidth > v.clientWidth ? l.scrollWidth : 0;
      setOverflow(w);
      if (w === 0) setPaused(false);
      // The loop moves one copy plus the gap between copies, at marquee.speed px per second.
      const speed = parseFloat(getComputedStyle(v).getPropertyValue("--sd-marquee-speed")) || 0;
      const gap = track.current ? parseFloat(getComputedStyle(track.current).columnGap) || 0 : 0;
      setLoop(speed > 0 ? (w + gap) / speed : 0);
    };
    measure();
    // Both the viewport and the text: a web font that loads late, or a size change, moves the text alone.
    const ro = new ResizeObserver(measure);
    ro.observe(v);
    ro.observe(l);
    return () => ro.disconnect();
  }, [text, secondary, size, paused]);

  const overflows = overflow > 0 && loop > 0 && !still;
  // Paused, the notice stops and wraps like the reduced-motion layout, so the whole text can be read.
  const moving = overflows && !paused;
  const style = moving ? ({ "--sd-marquee-loop": `${loop}s` } as CSSProperties) : undefined;
  // Still (reduced motion) and paused share one layout: the lines wrap, so the whole text shows.
  const wrapped = still || paused;

  return (
    <div ref={ref} className={className ? `sd-marquee ${className}` : "sd-marquee"} data-size={size}>
      <div ref={viewport} className="sd-marquee__viewport" data-wrapped={wrapped || undefined}>
        {/* key: a new text restarts the loop instead of jumping mid-scroll. */}
        <div key={text} ref={track} className="sd-marquee__track" data-moving={moving || undefined} data-wrapped={wrapped || undefined} style={style}>
          <span ref={line} className="sd-marquee__lines" data-wrapped={wrapped || undefined}>
            <span className={`sd-marquee__text sd-type-body-${size}-emphasized`}>{text}</span>
            {secondary && <span className={`sd-marquee__secondary sd-type-caption-${size}`}>{secondary}</span>}
          </span>
          {moving && (
            <span className="sd-marquee__lines" aria-hidden="true">
              <span className={`sd-marquee__text sd-type-body-${size}-emphasized`}>{text}</span>
              {secondary && <span className={`sd-marquee__secondary sd-type-caption-${size}`}>{secondary}</span>}
            </span>
          )}
        </div>
      </div>
      {/* Mounted while the text overflows, moving or paused, so pausing never drops focus. */}
      {overflows && (
        <ToggleButton className="sd-marquee__pause" aria-label={pauseLabel} isSelected={paused} onChange={setPaused} />
      )}
    </div>
  );
}

/* An opaque pill: the lines in a clipped viewport. While the text overflows, the track holds it twice
   and slides one copy's width, looping; reduced motion lets the lines wrap instead. */
.sd-marquee {
  position: relative;
  display: grid;
  min-inline-size: 0;
  background: var(--sd-marquee-background);
  color: var(--sd-marquee-foreground);
}
.sd-marquee[data-size="small"] {
  padding: var(--sd-marquee-padding-block-small) var(--sd-marquee-padding-inline-small);
  border-radius: var(--sd-marquee-radius-small);
  corner-shape: superellipse(var(--sd-radius-curve));
}
.sd-marquee[data-size="medium"] {
  padding: var(--sd-marquee-padding-block-medium) var(--sd-marquee-padding-inline-medium);
  border-radius: var(--sd-marquee-radius-medium);
  corner-shape: superellipse(var(--sd-radius-curve));
}
.sd-marquee[data-size="large"] {
  padding: var(--sd-marquee-padding-block-large) var(--sd-marquee-padding-inline-large);
  border-radius: var(--sd-marquee-radius-large);
  corner-shape: superellipse(var(--sd-radius-curve));
}

.sd-marquee__viewport {
  overflow: hidden;
}

.sd-marquee__track {
  display: flex;
  inline-size: max-content;
  gap: var(--sd-marquee-loop-gap);
}
.sd-marquee__track[data-moving] {
  animation: sd-marquee-scroll var(--sd-marquee-loop) linear infinite;
}

.sd-marquee__lines {
  display: flex;
  flex-direction: column;
  gap: var(--sd-marquee-gap);
  white-space: nowrap;
}

.sd-marquee__secondary {
  color: var(--sd-marquee-secondary-foreground);
}

/* Wrapped (reduced motion, or paused): the lines wrap and nothing is clipped, so the whole text shows. */
.sd-marquee__viewport[data-wrapped] {
  overflow: visible;
}
.sd-marquee__track[data-wrapped] {
  inline-size: auto;
}
.sd-marquee__lines[data-wrapped] {
  white-space: normal;
}

/* Right to left, the text starts at the right edge, so the loop runs the other way. Only the name:
   the duration comes from the moving rule above, so a still track has nothing to run. */
.sd-marquee__track:dir(rtl) {
  animation-name: sd-marquee-scroll-rtl;
}

/* The pause toggle covers the notice; pressing anywhere on it pauses or resumes. */
.sd-marquee__pause {
  position: absolute;
  inset: 0;
  margin: 0;
  padding: 0;
  border: 0;
  border-radius: inherit;
  corner-shape: inherit;
  background: transparent;
  cursor: pointer;
  outline: none;
}
.sd-marquee__pause[data-focus-visible] {
  box-shadow: 0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-state-focus-ring) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
  outline: var(--sd-state-focus-ring-width) solid transparent;
}

@keyframes sd-marquee-scroll {
  from {
    transform: translateX(0);
  }
  to {
    transform: translateX(calc(-50% - var(--sd-marquee-loop-gap) / 2));
  }
}

@keyframes sd-marquee-scroll-rtl {
  from {
    transform: translateX(0);
  }
  to {
    transform: translateX(calc(50% + var(--sd-marquee-loop-gap) / 2));
  }
}

/* Reduced motion: no scroll, and the lines wrap so nothing is cut off. */
@media (prefers-reduced-motion: reduce) {
  .sd-marquee__viewport {
    overflow: visible;
  }
  .sd-marquee__track {
    inline-size: auto;
    animation: none;
  }
  .sd-marquee__lines {
    white-space: normal;
  }
}
